import sys
from typing import Optional, Iterator, Tuple


def sqrti(b: int) -> int:
    n = 2
    if b < 2:
        return b
    n1 = n - 1
    n2 = n
    n3 = n1
    c = 1
    d = (n3 + b) // n2
    e = (n3 * d + b // (d ** n1)) // n2
    while c != d and c != e:
        c = d
        d = e
        e = (n3 * e + b // (e ** n1)) // n2
    return d if d < e else e


class Rects(Iterator[Tuple[int, int]]):
    def __init__(self, area: int, rw_start: int, rw_end: int, rh_start: int, rh_end: int, w: int):
        self.area = area
        self.rw_start = rw_start
        self.rw_end = rw_end
        self.rh_start = rh_start
        self.rh_end = rh_end
        self.w = w

    @classmethod
    def new(cls, area: int) -> "Rects":
        q = sqrti(area)
        return cls(area, 1, q, 1, area, q)

    @classmethod
    def with_limits(cls, area: int, rw_start: int, rw_end: int, rh_start: int, rh_end: int) -> "Rects":
        q = sqrti(area)
        maxw = min(q, area // rh_start, rw_end)
        minw = max(area // rh_end, rw_start)
        return cls(area, minw, maxw, rh_start, rh_end, maxw)

    def __iter__(self) -> "Rects":
        return self

    def __next__(self) -> Tuple[int, int]:
        while self.w >= self.rw_start:
            w = self.w
            self.w -= 1
            h = self.area // w
            if h < self.rh_start or h > self.rh_end or h * w != self.area:
                continue
            return (w, h)
        raise StopIteration


def solve(a: int, b: int) -> Optional[int]:
    if a < 1 or b < 1:
        return None
    area = a + b
    for ow, oh in Rects.new(area):
        perimeter = (ow + oh) * 2
        found = False
        for iw, ih in Rects.with_limits(a, 1, ow, 1, oh):
            if iw <= ow and ih <= oh:
                found = True
                break
        if not found:
            for iw, ih in Rects.with_limits(b, 1, ow, 1, oh):
                if iw <= ow and ih <= oh:
                    found = True
                    break
        if found:
            return perimeter
    return None


def input_pair() -> Tuple[int, int]:
    line = sys.stdin.readline()
    if not line:
        raise ValueError("Cannot read stdin")
    words = line.strip().split(' ')
    if len(words) < 2:
        raise ValueError("Cannot parse input")
    try:
        a = int(words[0])
        b = int(words[1])
    except ValueError:
        raise ValueError("Cannot parse input")
    return a, b


def main() -> None:
    try:
        a, b = input_pair()
        res = solve(a, b)
    except Exception as e:
        sys.stderr.write(f"Error: {e}\n")
        sys.exit(1)
    if res is not None:
        print(res)
    else:
        sys.stderr.write("Error: solution not found\n")
        sys.exit(1)


